class Truncate(Step):
    def __init__(self, length: int):
        self.length = length

    def apply(self, text: str) -> str:
        return text[: self.length]


class Upper(Step):
    def apply(self, text: str) -> str:
        return text.upper()


class Strip(Step):
    def apply(self, text: str) -> str:
        return text.strip()


class Squeeze(Step):
    def apply(self, text: str) -> str:
        return " ".join(text.split())

