"""Which name means which step."""

from pipeline.steps import Squeeze, Strip, Truncate, Upper

STEPS = {"upper": Upper(), "strip": Strip(), "squeeze": Squeeze()}


def lookup(name: str):
    if ":" in name:
        base, arg = name.split(":", 1)
        if base not in STEPS:
            raise KeyError(f"no step named {base!r}. Known: {', '.join(sorted(STEPS))}")
        if base == "truncate":
            if arg == "":
                raise ValueError(f"truncate requires a length argument")
            try:
                length = int(arg)
            except ValueError:
                raise ValueError(f"truncate length must be an integer, got {arg!r}")
            return Truncate(length)
        raise KeyError(f"step {base!r} does not take arguments")
    else:
        if name not in STEPS:
            raise KeyError(f"no step named {name!r}. Known: {', '.join(sorted(STEPS))}")
        return STEPS[name]

