        run_pipeline("x", ["nope"])


# truncate tests


def test_truncate_basic():
    assert run_pipeline("abcdef", ["truncate:3"]) == "abc"


def test_truncate_past_end():
    assert run_pipeline("abc", ["truncate:99"]) == "abc"


def test_truncate_zero():
    assert run_pipeline("abc", ["truncate:0"]) == ""


def test_truncate_missing_length():
    with pytest.raises(ValueError):
        run_pipeline("abc", ["truncate:"])


def test_truncate_non_numeric():
    with pytest.raises(ValueError):
        run_pipeline("abc", ["truncate:abc"])


def test_truncate_no_colon():
    with pytest.raises(ValueError):
        run_pipeline("abc", ["truncate"])


def test_truncate_strip_chain():
    assert run_pipeline("  hello world  ", ["strip", "truncate:5"]) == "hello"

